var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
if (!scene.IsValid()) { Debug.LogError("City not loaded"); return; }
var roots = scene.GetRootGameObjects();
Sim.Jobs.JobCompletionResultPanel comp = null;
foreach (var r in roots) {
    comp = r.GetComponentInChildren<Sim.Jobs.JobCompletionResultPanel>(true);
    if (comp != null) break;
}
if (comp == null) { Debug.LogError("panel not found"); return; }
Debug.Log("Panel path: " + comp.transform.name);
var modal = comp.transform.Find("Modal");
if (modal == null) { Debug.LogError("Modal not found"); return; }
Debug.Log("Modal instanceID=" + modal.GetInstanceID());
for (int i = 0; i < modal.childCount; i++) {
    var c = modal.GetChild(i);
    var comps = c.GetComponents<UnityEngine.Component>();
    string ct = "";
    foreach (var cm in comps) ct += cm.GetType().Name + ",";
    Debug.Log("[" + i + "] " + c.name + " iid=" + c.GetInstanceID() + " comps=" + ct);
}
